Configure alert settings.

```python
@app.post("/api/v1/alerts/configure")
async def configure_alerts(
    config: AlertConfig, credentials: HTTPAuthorizationCredentials = Depends(security)
):
    """Configure alert settings."""
    request_counter.labels(endpoint="configure_alerts").inc()

    try:
        # Verify authentication
        if not verify_token(credentials.credentials):
            raise HTTPException(status_code=401, detail="Invalid token")

        # Update alert configuration
        alert_manager.update_config(config.dict())

        return {
            "message": "Alert configuration updated",
            "timestamp": datetime.now().isoformat(),
        }

    except Exception as e:
        logger.error(f"Alert configuration failed: {str(e)}")
        raise HTTPException(status_code=500, detail=str(e))
```

Get fraud detection dashboard data.

```python
@app.get("/api/v1/analytics/dashboard")
async def get_fraud_dashboard(
    credentials: HTTPAuthorizationCredentials = Depends(security),
):
    """Get fraud detection dashboard data."""
    request_counter.labels(endpoint="fraud_dashboard").inc()

    try:
        # Verify authentication
        if not verify_token(credentials.credentials):
            raise HTTPException(status_code=401, detail="Invalid token")

        # Get dashboard data
        dashboard_data = {
            "total_transactions": transaction_processor.get_total_transactions(),
            "flagged_transactions": transaction_processor.get_flagged_transactions(),
            "fraud_rate": transaction_processor.get_fraud_rate(),
            "model_performance": {
                "fraud_detector_auc": fraud_detector.get_auc(),
                "risk_assessor_accuracy": risk_assessor.get_accuracy(),
            },
            "recent_alerts": await alert_manager.get_recent_alerts(),
            "timestamp": datetime.now().isoformat(),
        }

        return dashboard_data

    except Exception as e:
        logger.error(f"Dashboard data retrieval failed: {str(e)}")
        raise HTTPException(status_code=500, detail=str(e))
```
